151:         Map<String, ?> definitionMap = JsonUtils.readMap(workflow.getDefinition());
152: 
153:         WorkflowNodeStructure workflowNodeStructure = getWorkflowNodeStructure(workflowNodeName, definitionMap);
154: 
155:         Map<String, Object> metadataMap = getMetadataMap(workflowNodeName, definitionMap);
156: 
157:         Map<String, ?> dynamicPropertyTypesMap = getDynamicPropertyTypesMap(metadataMap);
158: 
159:         String[] parameterPathParts = parameterPath.split("\\.");
160: 
161:         setParameter(parameterPathParts, value, false, workflowNodeStructure.parameterMap);
162: 
163:         // For now only check the first, root level of properties on which other properties could depend on
164: 
165:         checkDependOn(
166:             parameterPathParts[0], workflowNodeStructure.properties(), workflowNodeStructure.parameterMap,
167:             dynamicPropertyTypesMap);
168: 
169:         Map<String, ?> inputMap = workflowTestConfigurationService.getWorkflowTestConfigurationInputs(
170:             workflow.getId());
171: 
172:         Map<String, Boolean> displayConditionMap = checkDisplayConditionsAndParameters(
173:             parameterPath, workflowNodeName, workflow, workflowNodeStructure.operationType,
174:             workflowNodeStructure.parameterMap, inputMap, dynamicPropertyTypesMap, workflowNodeStructure.properties,
175:             true);
176: 
177:         if (includeInMetadata) {
178:             setDynamicPropertyTypeItem(parameterPath, type, metadataMap);
179:         }
180: 
181:         workflowService.update(
182:             workflowId, JsonUtils.writeWithDefaultPrettyPrinter(definitionMap, true), workflow.getVersion());
183: 
184:         return new UpdateParameterResultDTO(
185:             displayConditionMap, metadataMap, workflowNodeStructure.missingRequiredProperties,
186:             workflowNodeStructure.parameterMap);
187:     }
