219:         String displayCondition, Map<String, Object> inputMap, Map<String, Object> outputs,
220:         Map<String, ?> parameterMap) {
221: 
222:         Map<String, Object> evaluate;
223: 
224:         try {
225:             evaluate = evaluator.evaluate(parameterMap, outputs);
226:         } catch (Exception e) {
227:             if (LOGGER.isTraceEnabled()) {
228:                 LOGGER.trace(e.getMessage());
229:             }
230: 
231:             evaluate = new HashMap<>(parameterMap);
232:         }
233: 
234:         return evaluate(
235:             displayCondition,
236:             MapUtils.concat(
