895: 
896:                 Matcher matcher = ARRAY_INDEX_VALUE_PATTERN.matcher(arrays);
897: 
898:                 List<Integer> arrayIndexes = new ArrayList<>();
899: 
900:                 while (matcher.find()) {
901:                     arrayIndexes.add(Integer.parseInt(matcher.group(1)));
902:                 }
903: 
904:                 for (int j = 0; j < arrayIndexes.size(); j++) {
905:                     int arrayIndex = arrayIndexes.get(j);
906: 
907:                     if (list.size() < (arrayIndex + 1)) {
908:                         for (int k = list.size(); k < (arrayIndex + 1); k++) {
909:                             list.add(null);
910:                         }
911:                     }
912: 
913:                     if (j == arrayIndexes.size() - 1) {
914:                         if (i == parameterPathParts.length - 1) {
915:                             if (removeValue) {
916:                                 list.remove(arrayIndex);
917:                             } else {
918:                                 list.set(arrayIndex, value);
919:                             }
920:                         } else {
921:                             if (list.get(arrayIndex) == null) {
