874:     private void setParameter(
875:         String[] parameterPathParts, Object value, boolean removeValue, Map<String, ?> parameterMap) {
876: 
877:         Map<String, Object> map = (Map<String, Object>) parameterMap;
878: 
879:         for (int i = 0; i < parameterPathParts.length; i++) {
880:             String pathItem = parameterPathParts[i];
881: 
882:             if (pathItem.endsWith("]")) {
883:                 String name = pathItem.substring(0, pathItem.indexOf("["));
884:                 String arrays = pathItem.substring(pathItem.indexOf("["));
885: 
886:                 List<Object> list;
887: 
888:                 if (Objects.nonNull(map.get(name))) {
889:                     list = (List<Object>) map.get(name);
